#!/usr/bin/env bash
set -euo pipefail
dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cp -r "$dir/fixtures"/. .

# Baseline committed BEFORE the "Generated by /vibe:sync on 2024-02-01" line,
# so only `git status --porcelain` reveals the new, uncommitted src/shipping/.
git init -q -b main
git config user.email "eval@example.com"
git config user.name "Eval Fixture"
git add -A
GIT_AUTHOR_DATE="2024-01-15T09:00:00" GIT_COMMITTER_DATE="2024-01-15T09:00:00" \
  git commit -q -m "chore: initial commit"

mkdir -p src/shipping
cat > src/shipping/index.js <<'EOF'
const { createClient } = require("axios-lite");

const http = createClient({ baseURL: "https://carrier.example.com" });

// Keeps the last 50 carrier responses so a flaky call can be replayed.
const retryBuffer = [];

// A parcel handed to a carrier for delivery to a customer.
// status goes "pending" -> "in_transit" -> "delivered".
function createShipment(orderId, address) {
  return { orderId, address, status: "pending", trackingCode: null };
}

async function dispatch(shipment) {
  const res = await http.post("/parcels", shipment);
  retryBuffer.push(res);
  if (retryBuffer.length > 50) retryBuffer.shift();
  return { ...shipment, status: "in_transit", trackingCode: res.data.code };
}

module.exports = { createShipment, dispatch };
EOF
